def orders_to_lines(apps, schema_editor):
    """Each existing order was one copy of one option: it becomes one line."""
    Order = apps.get_model('apiApp', 'PreSaleOrder')
    Item = apps.get_model('apiApp', 'PreSaleOrderItem')
    for order in Order.objects.all():
        delivered = order.status == 'entregado'
        Item.objects.create(
            order=order, option_id=order.option_id, quantity=1,
            unit_price=order.item_price + order.discount_applied, unit_discount=order.discount_applied,
            delivered_at=order.delivered_at if delivered else None,
            delivered_by_id=order.delivered_by_id if delivered else None,
        )


